// ✅ Number of top candidates to select
const TOP_N = 2;

// Get all input items
const items = $input.all();
if (!items || items.length === 0) return [];

// First, enrich each item by extracting candidateEmail from output string
const enrichedItems = items.map(item => {
  const rawOutput = item.json.output;

  let candidateEmail = null;

  if (rawOutput) {
    try {
      // Remove ```json and ``` wrappers
      const cleanedOutput = rawOutput
        .replace(/^```json/, '')
        .replace(/```$/, '')
        .trim();

      const parsed = JSON.parse(cleanedOutput);
      candidateEmail = parsed.candidateEmail || null;
    } catch (e) {
      candidateEmail = null;
    }
  }

  return {
    ...item,
    json: {
      ...item.json,
      candidateEmail
    }
  };
});

// Then normalize the match_score for sorting
const normalized = enrichedItems.map(item => {
  let score = item.json?.match_score;

  // Convert to numeric value even if it's a string like "85%" or "90/100"
  if (typeof score === 'string') {
    score = parseFloat(score.replace(/[^\d.-]+/g, '')) || 0;
  } else if (typeof score !== 'number') {
    score = 0;
  }

  return {
    ...item,
    json: {
      ...item.json,
      _score: score, // temp numeric score
    },
  };
});

// ✅ Sort in descending order by score
normalized.sort((a, b) => b.json._score - a.json._score);

// ✅ Take top N scores (including ties)
let topScoreItems = [];
let count = 0;
let lastScore = null;

for (const item of normalized) {
  if (count < TOP_N || item.json._score === lastScore) {
    topScoreItems.push(item);
    lastScore = item.json._score;
    count++;
  } else {
    break;
  }
}

// Remove temporary _score field
topScoreItems.forEach(item => delete item.json._score);

// ✅ Return enriched top items with candidateEmail extracted and preserved
return topScoreItems;
